begin;
with j as (select * from jsonb_to_recordset($law7d0063$[{"code_id":"NK_RF","article_number":"76","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.06.2011 № 162-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счету означает прекращение банком, а в отношении приостановления операций по счету цифрового рубля оператором платформы цифрового рубля всех расходных операций по данному счету, счету цифрового рубля, если иное не предусмотрено пунктом 2 настоящей статьи. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счету, по счету цифрового рубля не распространяется на платежи, очередность исполнения которых в соответствии с гражданским законодательством Российской Федерации предшествует исполнению обязанности по уплате налогов, сборов, страховых взносов, а также на операции по списанию денежных средств в счет уплаты налогов (авансовых платежей), сборов, страховых взносов, соответствующих пеней и штрафов и по их перечислению в бюджетную систему Российской Федерации. (В редакции  федеральных законов от 26.11.2008 № 224-ФЗ, от 03.07.2016 № 243-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nПриостановление переводов электронных денежных средств означает прекращение банком всех операций, влекущих уменьшение остатка электронных денежных средств, если иное не предусмотрено пунктом 2 настоящей статьи. (Дополнение абзацем - Федеральный закон от 27.06.2011 № 162-ФЗ)\n\nНе подлежат приостановлению операции по специальным избирательным счетам, специальным счетам фондов референдума и иным счетам в части сумм денежных средств, право собственности на которые не принадлежит владельцу соответствующего счета и на которые в соответствии с законодательством Российской Федерации не может быть обращено взыскание по обязательствам владельца этого счета. (Дополнение абзацем - Федеральный закон от 26.04.2016 № 110-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nПриостановление операций по счетам налогоплательщика-организации в банке, приостановление операций по счету цифрового рубля в случае, предусмотренном настоящим пунктом, означают прекращение банком, оператором платформы цифрового рубля расходных операций по счету (счетам), счету цифрового рубля этого налогоплательщика-организации в размере отрицательного сальдо его единого налогового счета, определяемом соответственно банком, оператором платформы цифрового рубля ежедневно на основании информации, содержащейся в реестре решений о взыскании задолженности, до момента формирования положительного либо нулевого сальдо его единого налогового счета, если иное не предусмотрено абзацем третьим пункта 1 настоящей статьи. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление переводов электронных денежных средств налогоплательщика-организации в случае, предусмотренном настоящим пунктом, означает прекращение банком операций, влекущих уменьшение остатка электронных денежных средств, в размере отрицательного сальдо единого налогового счета этого налогоплательщика-организации до момента формирования положительного либо нулевого сальдо его единого налогового счета, определяемом банком ежедневно на основании информации, содержащейся в реестре решений о взыскании задолженности.\n\nПриостановление операций налогоплательщика-организации по его валютному счету, счету в драгоценных металлах в банке либо переводов электронных денежных средств налогоплательщика-организации в иностранной валюте в случае, предусмотренном настоящим пунктом, означает прекращение банком расходных операций или операций, влекущих уменьшение остатка электронных денежных средств в иностранной валюте, в размере отрицательного сальдо единого налогового счета этого налогоплательщика-организации в рублях по курсу Центрального банка Российской Федерации или стоимости драгоценных металлов, определенной исходя из учетной цены на драгоценные металлы, установленных Центральным банком Российской Федерации на дату начала действия такого приостановления, до момента формирования положительного либо нулевого сальдо его единого налогового счета, определяемых банком на основании информации, содержащейся в реестре решений о взыскании задолженности.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n1) в случае непредставления этим налогоплательщиком-организацией налоговой декларации в налоговый орган в течение 20 дней по истечении установленного срока представления такой декларации - в течение трех лет со дня истечения срока, установленного настоящим подпунктом; (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n11) в случае неисполнения налогоплательщиком-организацией установленной пунктом 51 статьи 23 настоящего Кодекса обязанности по обеспечению получения от налогового органа по месту нахождения организации (по месту учета организации в качестве крупнейшего налогоплательщика) документов в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота - в течение 10 дней со дня установления налоговым органом факта неисполнения налогоплательщиком-организацией такой обязанности; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\n1) при принятии решения на основании подпункта 1 пункта 3 настоящей статьи - не позднее одного дня, следующего за днем представления налогоплательщиком-организацией налоговой декларации;\n\n11) при принятии решения на основании подпункта 11 пункта 3 настоящей статьи - не позднее одного дня, следующего за днем исполнения налогоплательщиком-организацией обязанности по обеспечению получения от налогового органа по месту нахождения организации (по месту учета организации в качестве крупнейшего налогоплательщика) документов в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, установленной пунктом 51 статьи 23 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nВ этом случае решение налогового органа о приостановлении операций налогового агента (плательщика страховых взносов) по его счетам в банке, по его счету цифрового рубля и переводов его электронных денежных средств отменяется решением этого налогового органа не позднее одного дня, следующего за днем представления указанным налоговым агентом (плательщиком страховых взносов) расчета сумм налога на доходы физических лиц, исчисленных и удержанных налоговым агентом (расчета по страховым взносам, расчета сумм выплаченных иностранным организациям доходов и удержанных налогов). (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.05.2015 № 113-ФЗ) (В редакции Федерального закона от 29.07.2018 № 232-ФЗ)\n\nРешение об отмене приостановления операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств направляется соответственно в банк, оператору платформы цифрового рубля в электронной форме не позднее дня, следующего за днем принятия такого решения.\n\nПорядок направления в банк, оператору платформы цифрового рубля в электронной форме решения налогового органа о приостановлении операций по счетам в банке, по счету цифрового рубля налогоплательщика-организации и переводов его электронных денежных средств или решения об отмене приостановления операций по счетам в банке, по счету цифрового рубля налогоплательщика-организации и переводов его электронных денежных средств устанавливается Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nФормы решения налогового органа о приостановлении операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств и решения об отмене приостановления операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. Форматы указанных решений утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации.\n\nКопия решения о приостановлении операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств или решения об отмене приостановления операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств передается налогоплательщику-организации под расписку или иным способом, свидетельствующим о дате получения налогоплательщиком-организацией копии соответствующего решения, в срок не позднее дня, следующего за днем принятия такого решения.\n\n(Пункт в редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nнежных средств, перевод которых приостановлен, в течение одного дня, следующего за днем приостановления операций по счетам налогоплательщика-организации в банке. Оператор платформы цифрового рубля обязан сообщить в налоговый орган в электронной форме сведения об остатках цифровых рублей на счете цифрового рубля, операции по которому приостановлены, в течение одного дня, следующего за днем приостановления операций по счету цифрового рубля налогоплательщика-организации. Форматы сообщения банком, оператором платформы цифрового рубля сведений об остатках денежных средств (драгоценных металлов) на счетах налогоплательщика-организации в банке, остатках цифровых рублей на счете цифрового рубля и об остатках электронных денежных средств и порядок направления банком, оператором платформы цифрового рубля указанного сообщения в электронной форме утверждаются Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nБанк обязан не позднее дня, следующего за днем, по состоянию на конец которого произошло изменение остатка денежных средств (драгоценных металлов) налогоплательщика-организации на счетах в банке, операции по которым приостановлены, а также остатка электронных денежных средств, перевод которых приостановлен, сообщать в налоговый орган в электронной форме сведения об остатках денежных средств (драгоценных металлов) и об остатках электронных денежных средств по состоянию на конец соответствующего операционного дня. Оператор платформы цифрового рубля обязан не позднее дня, следующего за днем, по состоянию на конец которого произошло изменение остатка цифровых рублей налогоплательщика-организации на счете цифрового рубля, сообщить в налоговый орган в электронной форме сведения об остатке цифровых рублей на счете цифрового рубля по состоянию на конец соответствующего операционного дня. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПри направлении в банк решения о приостановлении операций по счетам налогоплательщика-организации в банке и переводов его электронных денежных средств, оператору платформы цифрового рубля решения о приостановлении операций налогоплательщика-организации по счету цифрового рубля в электронной форме дата и время получения этих решений банком, оператором платформы цифрового рубля определяются в порядке, устанавливаемом Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nВ случае, если после приостановления операций по счетам налогоплательщика-организации в банке изменились наименование налогоплательщика-организации и (или) реквизиты счета налогоплательщика-организации в банке, операции по которому приостановлены налоговым органом, приостановление операций по счетам в банке применяется также в отношении налогоплательщика-организации, изменившей свое наименование, и операций по счету, имеющему измененные реквизиты. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ случае, если после приостановления переводов электронных денежных средств налогоплательщика-организации в банке изменились наименование налогоплательщика-организации и (или) реквизиты корпоративного электронного средства платежа налогоплательщика-организации, переводы электронных денежных средств с использованием которого приостановлены налоговым органом, приостановление переводов электронных денежных средств применяется также в отношении налогоплательщика-организации, изменившей свое наименование, и электронных денежных средств с использованием корпоративного электронного средства платежа, имеющего измененные реквизиты. (Дополнение абзацем - Федеральный закон от 27.06.2011 № 162-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ случае, если после приостановления операций по счету цифрового рубля налогоплательщика-организации изменились наименование налогоплательщика-организации и (или) реквизиты счета цифрового рубля налогоплательщика-организации, операции по которому приостановлены налоговым органом, приостановление операций по счету цифрового рубля применяется также в отношении налогоплательщика-организации, изменившей свое наименование, и операций по счету цифрового рубля, имеющему измененные реквизиты. (Дополнение абзацем - Федеральный закон от 19.12.2023 № 610-ФЗ)\n\nВ случае, если отмена приостановления операций по счетам налогоплательщика-организации в банке осуществляется по основаниям, предусмотренным иными федеральными законами, принятие налоговым органом решения об отмене приостановления таких операций не требуется.\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nВ случае неправомерного вынесения налоговым органом решения о приостановлении операций по счетам налогоплательщика-организации в банке на сумму денежных средств, в отношении которой действовало указанное решение (на драгоценные металлы, в отношении которых действовало указанное решение) налогового органа, начисляются проценты, подлежащие уплате указанному налогоплательщику-организации за каждый календарный день, начиная со дня получения банком решения о приостановлении операций по счетам налогоплательщика до дня получения банком решения об отмене приостановления операций по счетам налогоплательщика-организации. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции Федерального закона от 27.11.2017 № 343-ФЗ)\n\nПроцентная ставка принимается равной ставке рефинансирования Центрального банка Российской Федерации, действовавшей в дни неправомерного приостановления операций по счетам налогоплательщика-организации, нарушения налоговым органом срока отмены решения о приостановлении операций по счетам налогоплательщика-организации в банке или срока направления в банк решения об отмене приостановления операций по счетам налогоплательщика-организации в банке. При этом стоимость драгоценных металлов определяется исходя из учетной цены на драгоценные металлы, установленной Центральным банком Российской Федерации на дату неправомерного приостановления операций по счетам налогоплательщика-организации, нарушения налоговым органом срока отмены решения о приостановлении операций по счетам налогоплательщика-организации в банке или срока направления в банк решения об отмене приостановления операций по счетам налогоплательщика-организации в банке. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ; от 27.11.2017 № 343-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n1) организаций - налоговых агентов, плательщиков сборов, плательщиков страховых взносов; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n2) индивидуальных предпринимателей - налогоплательщиков, налоговых агентов, плательщиков сборов, плательщиков страховых взносов, не утративших статус индивидуального предпринимателя на дату принятия решения о взыскании (далее в настоящей статье - индивидуальный предприниматель);  (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n3) организаций и индивидуальных предпринимателей, не являющихся налогоплательщиками (налоговыми агентами, плательщиками страховых взносов), которые при этом обязаны представлять налоговые декларации (расчеты по страховым взносам) в соответствии с частью второй настоящего Кодекса; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n4) нотариусов, занимающихся частной практикой, адвокатов, учредивших адвокатские кабинеты, - налогоплательщиков, налоговых агентов, плательщиков страховых взносов. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\n12. В случае приостановления операций по счетам налогоплательщика-организации и переводов его электронных денежных средств в банке, приостановления операций по его счету цифрового рубля, а также по счетам лиц, указанных в пункте 11 настоящей статьи, их счетам цифрового рубля и открытия соответственно банком, оператором платформы цифрового рубля этой организации и этим лицам счета, счета цифрового рубля и (или) предоставления банком этой организации права использовать новые корпоративные электронные средства платежа (персонифицированные электронные средства платежа) для переводов электронных денежных средств все расходные операции по вновь открытым счетам, счету цифрового рубля и (или) по переводу электронных денежных средств этой организации и этих лиц прекращаются банком, а в отношении цифровых рублей оператором платформы цифрового рубля со дня открытия соответствующего счета, счета цифрового рубля и (или) предоставления права использовать корпоративные электронные средства платежа (персонифицированные электронные средства платежа) до прекращения действия приостановления операций по счетам, по счету цифрового рубля и (или) переводов электронных денежных средств этой организации и этих лиц либо до отмены налоговым органом приостановления операций по счетам, счету цифрового рубля и (или) переводов электронных денежных средств этой организации и этих лиц в соответствии с пунктами 91 и 93 настоящей статьи.\n\nПорядок информирования банков о приостановлении операций по счетам в банке налогоплательщика-организации, лиц, указанных в пункте 11 настоящей статьи, и переводов их электронных денежных средств, информирования оператора платформы цифрового рубля о приостановлении операций по счетам цифрового рубля налогоплательщика-организации, лиц, указанных в пункте 11 настоящей статьи, устанавливается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации.\n\nНе подлежат приостановлению в соответствии с настоящим пунктом операции по специальным избирательным счетам, специальным счетам фондов референдума и иным счетам в части сумм денежных средств, право собственности на которые не принадлежит владельцу соответствующего счета и на которые в соответствии с законодательством Российской Федерации не может быть обращено взыскание по обязательствам владельца этого счета.\n\nПриостановление операций по счету в соответствии с настоящим пунктом не распространяется на платежи, очередность исполнения которых в соответствии с гражданским законодательством предшествует исполнению обязанности по уплате налогов, сборов, страховых взносов, а также на операции по списанию денежных средств в счет уплаты налогов (авансовых платежей), сборов, страховых взносов, соответствующих пеней и штрафов и по их перечислению в бюджетную систему Российской Федерации.\n\n(Пункт в редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 76. Приостановление операций по счетам в банках, по счетам цифрового рубля, а также переводов электронных денежных средств организаций и индивидуальных предпринимателей","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bec87037ae57dcd934a74028df4811fb424da018d32c90bb3080062b9d44b741"},{"code_id":"NK_RF","article_number":"77","version_date":"2000-07-31","article_text":"Арест имущества производится в случае неисполнения налогоплательщиком-организацией в установленные сроки обязанности по уплате налога, пеней и штрафов и при наличии у налоговых или таможенных органов достаточных оснований полагать, что указанное лицо предпримет меры, чтобы скрыться либо скрыть свое имущество. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nПолным арестом имущества признается такое ограничение прав налогоплательщика-организации в отношении его имущества, при котором он не вправе распоряжаться арестованным имуществом, а владение и пользование этим имуществом осуществляются с разрешения и под контролем налогового или таможенного органа. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nЧастичным арестом признается такое ограничение прав налогоплательщика-организации в отношении его имущества, при котором владение, пользование и распоряжение этим имуществом осуществляются с разрешения и под контролем налогового или таможенного органа. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nРешение о наложении ареста может быть принято в отношении общего имущества товарищей, а при отсутствии или недостаточности такого имущества в отношении имущества всех управляющих товарищей (при этом в первую очередь такое решение принимается в отношении имущества управляющего товарища, ответственного за ведение налогового учета).\n\nРешение о наложении ареста на общее имущество товарищей принимается руководителем (заместителем руководителя) уполномоченного налогового органа. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nРешение о наложении ареста на общее имущество товарищей и имущество управляющих товарищей может быть принято не ранее принятия решения о взыскании задолженности в соответствии со статьей 46 настоящего Кодекса и при недостаточности или отсутствии денежных средств на счетах инвестиционного товарищества, лиц, являющихся управляющими товарищами, либо при отсутствии информации о счетах указанных лиц.  (В редакции  федеральных законов от 23.07.2013 № 248-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\nАрест на объект недвижимого имущества иностранной организации, не осуществляющей деятельность в Российской Федерации через постоянное представительство, при превышении стоимости указанного объекта недвижимого имущества над суммой взыскиваемой задолженности в отношении этого объекта налагается в случае отсутствия у иностранной организации иного имущества на территории Российской Федерации, на которое может быть обращено взыскание. (Дополнение абзацем - Федеральный закон от 04.11.2\n\n014 № 347-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nЛицам, участвующим в производстве ареста имущества в качестве понятых, специалистов, а также налогоплательщику-организации (его представителю) разъясняются их права и обязанности. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n10. При производстве ареста составляется протокол об аресте имущества. В этом протоколе либо в прилагаемой к нему описи перечисляется и описывается имущество, подлежащее аресту, с точным указанием наименования, количества и индивидуальных признаков предметов, а при возможности - их стоимости.\n\nВсе предметы, подлежащие аресту, предъявляются понятым и налогоплательщику-организации (его представителю). (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n11. Руководитель (его заместитель) налогового или таможенного органа, вынесший постановление о наложении ареста на имущество, определяет место, где должно находиться имущество, на которое наложен арест.\n\n1) банковскую гарантию, отвечающую требованиям, установленным статьей 741 настоящего Кодекса и подтверждающую, что гарант обязывается перед налоговыми органами уплатить в соответствии с условиями даваемого гарантом обязательства сумму задолженности налогоплательщика-организации в случае неуплаты этой суммы принципалом в установленный срок по представленному налоговым органом гаранту в письменной форме или электронной форме по телекоммуникационным каналам связи требованию об уплате этой суммы; (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n2) залог имущества налогоплательщика-организации, оформленный в соответствии с пунктом 2 статьи 73 настоящего Кодекса;\n\n3) поручительство третьего лица, оформленное в порядке, предусмотренном статьей 74 настоящего Кодекса.\n\nВ целях настоящего подпункта поручитель должен соответствовать требованиям, установленным пунктом 21 статьи 1761 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 23.07.2013 № 248-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nРешение об аресте имущества действует с момента наложения ареста до отмены этого решения налоговым или таможенным органом, вынесшим это решение, либо до отмены этого решения вышестоящим налоговым или таможенным органом или судом. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nНалоговый (таможенный) орган уведомляет налогоплательщика об отмене решения об аресте имущества в течение пяти дней после дня принятия данного решения. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nС момента признания имущества находящимся в залоге у налогового органа ранее наложенный на это имущество арест прекращается. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Наименование в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 77. Арест имущества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"363be3353449fe6330ee236efe007cfa4e803cb7992b5a5a805141a66c80f559"},{"code_id":"NK_RF","article_number":"78","version_date":"2000-07-31","article_text":"1. Налогоплательщик, плательщик сбора, плательщик страховых взносов и (или) налоговый агент вправе распорядиться суммой денежных средств, формирующих положительное сальдо его единого налогового счета, путем зачета в порядке, предусмотренном настоящей статьей:\n\nв счет исполнения обязанности другого лица по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов;\n\nв счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса);\n\nв счет исполнения решений налоговых органов, указанных в подпунктах 9 и 10 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, либо погашения задолженности, не учитываемой в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса. (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\nВ случае отсутствия положительного сальдо на едином налоговом счете для исполнения заявления о распоряжении путем зачета налогоплательщику, плательщику сбора, плательщику страховых взносов и (или) налоговому агенту направляется сообщение об отказе в исполнении заявления о распоряжении путем зачета.\n\nВ случае недостаточности положительного сальдо на едином налоговом счете для исполнения заявления о распоряжении путем зачета в полном объеме зачет осуществляется частично.\n\nВ заявлении о распоряжении путем зачета в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) указываются принадлежность денежных средств к источнику доходов бюджетов бюджетной системы Российской Федерации, срок уплаты и иные реквизиты, необходимые для определения соответствующей обязанности.\n\nЗаявление о распоряжении путем зачета в счет исполнения решений налоговых органов, указанных в подпунктах 9 и 10 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, либо погашения задолженности, не учитываемой в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса, может быть подано не позднее дня, предшествующего дню вступления в силу судебного акта о взыскании задолженности, с указанием соответствующего решения налогового органа. Зачет осуществляется последовательно начиная с задолженности с наиболее ранними сроками уплаты. (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\nФорма и формат заявления о распоряжении путем зачета утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nИндивидуальными предпринимателями заявление о распоряжении путем зачета в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) может быть представлено в налоговый орган через личный кабинет налогоплательщика в виде документа, подписанного усиленной неквалифицированной электронной подписью, сформированной в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в соответствии с требованиями Федерального закона от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\". (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае, если на момент проведения указанного в абзаце первом настоящего пункта зачета суммы, формирующей положительное сальдо единого налогового счета налогоплательщика, недостаточно для исполнения в полном объеме обязанностей такого налогоплательщика по уплате налогов, подлежащих уплате на основании направленного ему налогового уведомления, такой зачет осуществляется пропорционально суммам таких обязанностей.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае одновременного поступления уведомления, указанного в пункте 7 настоящей статьи, и уведомления, указанного в абзаце первом настоящего пункта, зачет, предусмотренный абзацем первым настоящего пункта, осуществляется после зачета, предусмотренного пунктом 7 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 78. Зачет сумм денежных средств, формирующих положительное сальдо единого налогового счета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5adf94c53adcd7f9e13bc19754ea7a3bb4c4cb22aa4fbd39847f0382547bd0e6"},{"code_id":"NK_RF","article_number":"79","version_date":"2000-07-31","article_text":"1. Налогоплательщик, плательщик сбора, плательщик страховых взносов и (или) налоговый агент вправе распорядиться суммой денежных средств, формирующих положительное сальдо его единого налогового счета, путем возврата этой суммы на открытый ему счет в банке в порядке, предусмотренном настоящей статьей.\n\nРаспоряжение денежными средствами в размере сумм, формирующих положительное сальдо единого налогового счета налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента, осуществляется на основании:\n\nзаявления о распоряжении путем возврата сумм денежных средств, формирующих положительное сальдо единого налогового счета такого лица (далее - заявление о распоряжении путем возврата), представленного в налоговый орган по месту учета такого лица по установленной форме на бумажном носителе или по установленному формату в электронной форме с усиленной квалифицированной электронной подписью по телекоммуникационным каналам связи или представленного через личный кабинет налогоплательщика, а также в составе налоговой декларации в соответствии со статьей 229 настоящего Кодекса;\n\nзаявления о возврате излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в соответствии со статьей 2271 настоящего Кодекса, налога на профессиональный доход и сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  представленного в налоговый орган; (В редакции  федеральных законов от 28.12.2022 № 565-ФЗ, от 04.08.2023 № 415-ФЗ, от 12.07.2024 № 176-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nзаявления о возврате излишне уплаченных сумм страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности, представленного в налоговый орган плательщиком страховых взносов, включенным в порядке, предусмотренном Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\", в соответствующие перечни; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nпринятого налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 1761 или 2031 настоящего Кодекса;\n\nпринятого налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 176 или 203 либо решения о предоставлении налогового вычета в соответствии со статьей 2211 настоящего Кодекса.\n\nФорма заявления о распоряжении путем возврата и формат указанного заявления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. В случае отсутствия положительного сальдо на едином налоговом счете налогоплательщику, плательщику сбора, плательщику страховых взносов и (или) налоговому агенту направляется сообщение об отказе в возврате.\n\nВ случае недостаточности положительного сальдо на едином налоговом счете для осуществления предусмотренного настоящей статьей возврата сумм денежных средств налогоплательщику, плательщику сбора, плательщику страховых взносов и (или) налоговому агенту возврат осуществляется частично.\n\n3. Поручение о возврате суммы денежных средств, формирующих положительное сальдо единого налогового счета лица - налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента, направляется налоговым органом в территориальный орган Федерального казначейства не позднее следующего дня после наступления одного из следующих событий:\n\nполучение заявления о распоряжении путем возврата, но не ранее принятия решений о возмещении (полностью или частично) суммы налога, заявленной к возмещению, в соответствии со статьями 176 и 203 настоящего Кодекса, решения о предоставлении налогового вычета в соответствии со статьей 2211 настоящего Кодекса, если иное не предусмотрено настоящим пунктом; (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\nпризнание в соответствии с подпунктом 5 пункта 1 статьи 113 настоящего Кодекса единым налоговым платежом излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности после получения заявления о возврате сумм соответствующих излишне уплаченных налогов, сборов или страховых взносов; (В редакции  федеральных законов от 04.08.2023 № 415-ФЗ, от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nпринятие налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 1761 или 2031 настоящего Кодекса;\n\nполучение заявления о распоряжении путем возврата суммы денежных средств, формирующих положительное сальдо единого налогового счета, представленного в соответствии со статьей 229 настоящего Кодекса одновременно с налоговой декларацией по налогу на доходы физических лиц, но не ранее дня\n\nвступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанной налоговой декларации либо истечения 10 дней после дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанной налоговой декларации. В случае, если при проведении камеральной налоговой проверки указанной налоговой декларации не были выявлены нарушения законодательства о налогах и сборах, указанное в абзаце первом настоящего пункта поручение о возврате суммы денежных средств может быть направлено налоговым органом в территориальный орган Федерального казначейства раньше дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанной налоговой декларации. (Дополнение абзацем - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n4. В случае, если установлен факт излишнего взыскания денежных средств, возврат излишне взысканных средств осуществляется налоговым органом самостоятельно в пределах сумм, формирующих положительное сальдо единого налогового счета.\n\nВозврат излишне взысканных денежных средств осуществляется на открытый счет организации, индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем, в банке, информация о котором имеется у налоговых органов.\n\nПроценты на сумму излишне взысканных денежных средств начисляются со дня, следующего за днем взыскания, по день фактического возврата излишне взысканных сумм либо учета излишне взысканных сумм в счет исполнения совокупной обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента.\n\nПроцентная ставка принимается равной действовавшей в эти дни ключевой ставке Центрального банка Российской Федерации.\n\n5. Возврат сумм денежных средств, формирующих положительное сальдо единого налогового счета лица - налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента, осуществляется в валюте Российской Федерации посредством перечисления суммы денежных средств в размере, не превышающем положительное сальдо единого налогового счета такого лица по состоянию на дату формирования поручения о возврате денежных средств, на указанный в соответствующем заявлении счет в банке, информация о котором имеется у налоговых органов и который открыт такому лицу либо иностранному номинальному держателю (иностранному уполномоченному держателю, лицу, которому открыт счет депозитарных программ), в случае, если через такое лицо налогоплательщику осуществлялась выплата дохода, особенности исчисления и уплаты налога с которого установлены статьей 3101 настоящего Кодекса.\n\nполучения заявления лица о распоряжении путем возврата, но не ранее принятия налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или акциза в соответствии со статьей 176 или 203 настоящего Кодекса либо решения о предоставлении налогового вычета в соответствии со статьей 2211 настоящего Кодекса;\n\nпризнания в соответствии с подпунктом 5 пункта 1 статьи 113 настоящего Кодекса единым налоговым платежом излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности после получения заявления о возврате сумм соответствующих излишне уплаченных налогов, сборов или страховых взносов; (В редакции  федеральных законов от 04.08.2023 № 415-ФЗ, от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nпринятия налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 1761 или 2031 настоящего Кодекса.\n\nПроцентная ставка принимается равной ключевой ставке Центрального банка Российской Федерации, действовавшей в дни нарушения срока перечисления указанных сумм денежных средств.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Наименование в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n(Наименование в редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 79. Возврат денежных средств, формирующих положительное сальдо единого налогового счета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef87020d43f6244676a7012bbc0355b146e502263ffab0a694b15e0617b35d4d"},{"code_id":"NK_RF","article_number":"8","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Под налогом понимается обязательный, индивидуально безвозмездный платеж, взимаемый с организаций и физических лиц в форме отчуждения принадлежащих им на праве собственности, хозяйственного ведения или оперативного управления денежных средств в целях финансового обеспечения деятельности государства и (или) муниципальных образований.\n\nДля целей настоящего Кодекса страховыми взносами также признаются взносы, взимаемые с организаций в целях дополнительного социального обеспечения отдельных категорий физических лиц.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 243-ФЗ)","article_title":"Статья 8. Понятие налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4471cb6a43e860b5c91058be95389aa56d47260f4b7f21e90aad3c8486c30624"},{"code_id":"NK_RF","article_number":"80","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nНалоговая декларация представляется каждым налогоплательщиком по каждому налогу, подлежащему уплате этим налогоплательщиком, если иное не предусмотрено законодательством о налогах и сборах.\n\nРасчет авансового платежа представляет собой письменное заявление или заявление налогоплательщика, составленное в электронной форме и переданное по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи или через личный кабинет налогоплательщика, о базе исчисления, об используемых льготах, исчисленной сумме авансового платежа и (или) о других данных, служащих основанием для исчисления и уплаты авансового платежа. Расчет авансового платежа представляется в случаях, предусмотренных настоящим Кодексом применительно к конкретному налогу. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ; от 04.11.2014 № 347-ФЗ)\n\nРасчет сбора представляет собой письменное заявление или заявление плательщика сбора, составленное в электронной форме и переданное по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи или через личный кабинет налогоплательщика, об объектах обложения, облагаемой базе, используемых льготах, исчисленной сумме сбора и (или) о других данных, служащих основанием для исчисления и уплаты сбора, если иное не предусмотрено настоящим Кодексом. Расчет сбора представляется в случаях, предусмотренных частью второй настоящего Кодекса применительно к каждому сбору. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ; от 04.11.2014 № 347-ФЗ)\n\nНалоговый агент представляет в налоговые органы расчеты, предусмотренные частью второй настоящего Кодекса. Указанные расчеты представляются в порядке, установленном частью второй настоящего Кодекса применительно к конкретному налогу.\n\nРасчет сумм налога на доходы физических лиц, исчисленных и удержанных налоговым агентом, представляет собой документ, содержащий обобщенную налоговым агентом информацию в целом по всем физическим лицам, получившим доходы от налогового агента (обособленного подразделения налогового агента), о суммах начисленных и выплаченных им доходов, предоставленных налоговых вычетах, об исчисленных и удержанных суммах налога, а также других данных, служащих основанием для исчисления налога. (Дополнение абзацем - Федеральный закон от 02.05.2015 № 113-ФЗ)\n\nРасчет по страховым взносам представляет собой письменное заявление или заявление плательщика страховых взносов, составленное в электронной форме и переданное по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи или через личный кабинет налогоплательщика, об объекте обложения страховыми взносами, о базе для исчисления страховых взносов, об исчисленной сумме страховых взносов и о других данных, служащих основанием для исчисления и уплаты страховых взносов, если иное не предусмотрено настоящим Кодексом. Расчет по страховым взносам представляется в случаях, предусмотренных главой 34 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nЛицо, признаваемое налогоплательщиком по одному или нескольким налогам, не осуществляющее операций, в результате которых происходит движение денежных средств на его счетах в банках (в кассе организации), и не имеющее по этим налогам объектов налогообложения, представляет по данным налогам единую (упрощенную) налоговую декларацию.\n\nФорма единой (упрощенной) налоговой декларации и порядок ее заполнения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Министерством финансов Российской Федерации. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nЕдиная (упрощенная) налоговая декларация представляется в налоговый орган по месту нахождения организации или месту жительства физического лица в следующие сроки: (В редакции Федерального закона от 08.08.2024 № 259-ФЗ)\n\nпо налогу на прибыль организаций - не позднее 20-го числа первого месяца второго квартала, следующего за налоговым периодом, в котором последний раз осуществлялись операции, в результате которых происходило движение денежных средств на счетах в банках (в кассе организации) этого лица, и (или) в котором последний раз были объекты налогообложения по налогу на прибыль организаций; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nпо остальным налогам - не позднее 20-го числа первого месяца второго налогового периода, следующего за налоговым периодом, в котором последний раз осуществлялись операции, в результате которых происходило движение денежных средств на счетах в банках (в кассе организации) этого лица, и (или) в котором последний раз были объекты налогообложения по налогам, по которым представляется единая (упрощенная) налоговая декларация; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nдля вновь созданных организаций, вновь зарегистрированных индивидуальных предпринимателей - не позднее 20-го числа месяца, следующего за истекшим кварталом, в котором была создана организация, был зарегистрирован индивидуальный предприниматель. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.12.2006 № 268-ФЗ)\n\nНалоговые декларации (расчеты) представляются в налоговый орган по месту учета налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) по установленным форматам в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, являющегося российской организацией и соответствующего требованиям, утверждаемым федеральным органом исполнительной власти, уполномоченным осуществлять функции по контролю и надзору в сфере налогов и сборов, если иной порядок представления информации, отнесенной к государственной тайне, не предусмотрен законодательством Российской Федерации, следующими категориями налогоплательщиков (плательщиков страховых взносов): (В редакции федеральных законов от 28.06.2013 № 134-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nналогоплательщиками (плательщиками страховых взносов), среднесписочная численность работников которых за предшествующий календарный год превышает 100 человек; (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nвновь созданными (в том числе при реорганизации) организациями, численность работников которых превышает 100 человек; (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nналогоплательщиками (плательщиками страховых взносов), не указанными в абзацах третьем и четвертом настоящего пункта, для которых такая обязанность предусмотрена частью второй настоящего Кодекса применительно к конкретному налогу (страховым взносам). (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nСведения о среднесписочной численности работников представляются в налоговые органы плательщиками страховых взносов, производящими выплаты и иные вознаграждения физическим лицам, в составе расчета по страховым взносам. (В редакции Федерального закона от 28.01.2020 № 5-ФЗ)\n\nНалогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, представляют все налоговые декларации (расчеты), которые они обязаны представлять в соответствии с настоящим Кодексом, в налоговый орган по месту учета в качестве крупнейших налогоплательщиков по установленным форматам в электронной форме, если иной порядок представления информации, отнесенной к государственной тайне, не предусмотрен законодательством Российской Федерации. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nБланки налоговых деклараций (расчетов) предоставляются налоговыми органами бесплатно.\n\n(Пункт в редакции Федерального закона от 30.12.2006 № 268-ФЗ)\n\nНалоговый орган не вправе отказать в принятии налоговой декларации (расчета), представленной налогоплательщиком (плательщиком сборов, плательщиком страховых взносов, налоговым агентом) по установленной форме (установленному формату), если иное не предусмотрено настоящим Кодексом, и обязан проставить по просьбе налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) на копии налоговой декларации (копии расчета) отметку о принятии и дату ее получения при получении налоговой декларации (расчета) на бумажном носителе (в том числе через многофункциональный центр предоставления государственных и муниципальных услуг) либо передать налогоплательщику (плательщику сбора, плательщику страховых взносов, налоговому агенту) квитанцию о приеме в электронной форме - при получении налоговой декларации (расчета) по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. (В редакции федеральных законов от 30.12.2006 № 268-ФЗ, от 29.06.2012 № 97-ФЗ, от 04.11.2014 № 347-ФЗ, от 03.07.2016 № 243-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nПри отправке налоговой декларации (расчета) по почте днем ее представления считается дата отправки почтового отправления с описью вложения, если иное не предусмотрено настоящим Кодексом. При передаче налоговой декларации (расчета) по телекоммуникационным каналам связи или через личный кабинет налогоплательщика днем ее представления считается дата ее отправки, если иное не предусмотрено настоящим Кодексом. (В редакции федеральных законов от 04.11.2014 № 347-ФЗ, от 23.11.2020 № 374-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nНалоговая декларация по налогу на доходы физических лиц на бумажном носителе также может быть представлена физическим лицом в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг, который при принятии налоговой декларации обязан проставить по просьбе налогоплательщика на копии налоговой декларации отметку о принятии и дату ее приема. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nДнем представления налоговой декларации по налогу на доходы физических лиц в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг считается день ее приема многофункциональным центром предоставления государственных и муниципальных услуг, если иное не предусмотрено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n1) в ходе проведения мероприятий налогового контроля установлен факт подписания налоговой декларации (расчета) неуполномоченным лицом;\n\n2) физическое лицо, имеющее право без доверенности действовать от имени налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) и подписавшее налоговую декларацию (расчет), дисквалифицировано на основании вступившего в силу постановления о дисквалификации по делу об административном правонарушении и срок, на который установлена дисквалификация, не исте\n\nк ранее даты представления в налоговый орган такой налоговой декларации (расчета);\n\n3) в Едином государственном реестре записей актов гражданского состояния содержатся сведения о дате смерти физического лица, наступившей ранее даты подписания налоговой декларации (расчета) усиленной квалифицированной электронной подписью этого физического лица;\n\n4) в отношении лица, имеющего право без доверенности действовать от имени налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) и подписавшего налоговую декларацию (расчет), в Единый государственный реестр юридических лиц внесена запись о недостоверности сведений об указанном лице ранее даты представления в налоговый орган такой налоговой декларации (расчета);\n\n5) в отношении налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) - организации в Единый государственный реестр юридических лиц внесена запись о прекращении юридического лица (путем реорганизации, ликвидации или исключения из Единого государственного реестра юридических лиц по решению регистрирующего органа) ранее даты представления таким лицом в налоговый орган налоговой декларации (расчета);\n\n6) обстоятельства, предусмотренные пунктом 53 статьи 174 либо пунктом 7 статьи 431 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nФорма и формат уведомления о признании налоговой декларации (расчета) непредставленной утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nНалогоплательщик (плательщик сбора, плательщика страховых взносов, налоговый агент) или его представитель подписывает налоговую декларацию (расчет), подтверждая достоверность и полноту сведений, указанных в налоговой декларации (расчете). (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nЕсли достоверность и полноту сведений, указанных в налоговой декларации (расчете), в том числе с применением усиленной квалифицированной электронной подписи при представлении налоговой декларации (расчета) в электронной форме, подтверждает уполномоченный представитель налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента), в налоговой декларации (расчете) указывается основание представительства (наименование документа, подтверждающего наличие полномочий на подписание налоговой декларации (расчета). При этом к налоговой декларации (расчету) прилагается копия документа, подтверждающего полномочия представителя на подписание налоговой декларации (расчета). (В редакции  федеральных законов от 27.07.2010 № 229-ФЗ, от 29.06.2012 № 97-ФЗ, от 03.07.2016 № 243-ФЗ, от 23.11.2020 № 374-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (Утратил силу  - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 30.12.2006 № 268-ФЗ) (Утратил силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов, сборов, страховых взносов, не вправе включать в форму налоговой декларации (расчета), а налоговые органы не вправе требовать от налогоплательщиков (плательщиков сборов, плательщиков страховых взносов, налоговых агентов) включения в налоговую декларацию (расчет) сведений, не связанных с исчислением и (или) уплатой налогов, сборов, страховых взносов, за исключением: (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n1) вида документа: первичный (корректирующий);\n\n2) наименования налогового органа;\n\n3) места нахождения организации (ее обособленного подразделения) или места жительства физического лица;\n\n4) фамилии, имени, отчества физического лица или полного наименования организации (ее обособленного подразделения);\n\n5) номера контактного телефона налогоплательщика, плательщика страховых взносов; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n6) сведений, подлежащих включению в налоговую декларацию в соответствии с главами 21, 23, 30 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции федеральных законов от 29.09.2019 № 325-ФЗ, от 23.11.2020 № 374-ФЗ)\n\n7) сведений о среднесписочной численности работников, подлежащих включению в расчет по страховым взносам. (Дополнение подпунктом - Федеральный закон от 28.01.2020 № 5-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 80. Налоговая декларация, расчеты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0a900994fa7e126f58af0e94644e1ef42dc1d3335e06be7849dad7f85ac0c68"},{"code_id":"NK_RF","article_number":"81","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. При обнаружении налогоплательщиком в поданной им в налоговый орган налоговой декларации факта неотражения или неполноты отражения сведений, а также ошибок, приводящих к занижению суммы налога, подлежащей уплате, налогоплательщик обязан внести необходимые изменения в налоговую декларацию и представить в налоговый орган уточненную налоговую декларацию в порядке, установленном настоящей статьей.\n\nПри обнаружении налогоплательщиком в поданной им в налоговый орган налоговой декларации недостоверных сведений, а также ошибок, не приводящих к занижению суммы налога, подлежащей уплате, налогоплательщик вправе внести необходимые изменения в налоговую декларацию и представить в налоговый орган уточненную налоговую декларацию в порядке, установленном настоящей статьей. При этом уточненная налоговая декларация, представленная после истечения установленного срока подачи декларации, не считается представленной с нарушением срока.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 01.05.2022 № 120-ФЗ) (Утратил силу  - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n2. Если уточненная налоговая декларация представляется в налоговый орган до истечения срока подачи налоговой декларации, она считается поданной в день подачи уточненной налоговой декларации.\n\n3. Если уточненная налоговая декларация представляется в налоговый орган после истечения срока подачи налоговой декларации, но до истечения срока уплаты налога, то налогоплательщик освобождается от ответственности, если уточненная налоговая декларация была представлена до момента, когда налогоплательщик узнал об обнаружении налоговым органом факта неотражения или неполноты отражения сведений в налоговой декларации, а также ошибок, приводящих к занижению подлежащей уплате суммы налога, либо о назначении выездной налоговой проверки.\n\n4. Если уточненная налоговая декларация представляется в налоговый орган после истечения срока подачи налоговой декларации и срока уплаты налога, то налогоплательщик освобождается от ответственности в случаях:\n\n1) представления уточненной налоговой декларации до момента, когда налогоплательщик узнал об обнаружении налоговым органом неотражения или неполноты отражения сведений в налоговой декларации, а также ошибок, приводящих к занижению подлежащей уплате суммы налога, либо о назначении выездной налоговой проверки по данному налогу за данный период, при условии, что на момент представления уточненной налоговой декларации имеется положительное сальдо единого налогового счета в размере, соответствующем недостающей сумме налога и соответствующих ей пеней; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2) представления уточненной налоговой декларации после проведения выездной налоговой проверки за соответствующий налоговый период, по результатам которой не были обнаружены неотражение или неполнота отражения сведений в налоговой декларации, а также ошибки, приводящие к занижению подлежащей уплате суммы налога.\n\n5. Уточненная налоговая декларация представляется налогоплательщиком в налоговый орган по месту учета.\n\nУточненная налоговая декларация (расчет) представляется в налоговый орган по форме, действовавшей в налоговый период, за который вносятся соответствующие изменения.\n\n6. При обнаружении налоговым агентом в поданном им в налоговый орган расчете факта неотражения или неполноты отражения сведений, а также ошибок, приводящих к занижению или завышению суммы налога, подлежащей перечислению, налоговый агент обязан внести в указанный расчет необходимые изменения и представить в налоговый орган уточненный расчет в порядке, установленном настоящей статьей.\n\nУточненный расчет, представляемый налоговым агентом в налоговый орган, за исключением расчета сумм выплаченных иностранным организациям доходов и удержанных налогов за прошедший отчетный (налоговый) период, должен содержать данные в отношении только тех налогоплательщиков, в отношении которых обнаружены факты неотражения или неполноты отражения сведений, а также ошибки, приводящие к занижению или завышению суммы налога.\n\nУточненный расчет сумм выплаченных иностранным организациям доходов и удержанных налогов за прошедший отчетный (налоговый) период должен содержать данные в отношении всех налогоплательщиков, указанных в ранее представленном в налоговый орган расчете.\n\nПоложения, предусмотренные пунктами 3 и 4 настоящей статьи, касающиеся освобождения от ответственности, применяются также в отношении налоговых агентов при представлении ими уточненных расчетов.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n61. В случае, если участник договора инвестиционного товарищества - управляющий товарищ, ответственный за ведение налогового учета (далее в настоящей статье - управляющий товарищ, ответственный за ведение налогового учета), предоставил участникам договора инвестиционного товарищества копию уточненного расчета финансового результата инвестиционного товарищества, налогоплательщики, уплачивающие налог на прибыль организаций, налог на доходы физических лиц в связи с их участием в договоре инвестиционного товарищества, обязаны подавать уточненную налоговую декларацию (расчет).\n\nУточненная налоговая декларация (расчет) должна быть представлена в налоговый орган по месту учета участника договора инвестиционного товарищества не позднее пятнадцати дней со дня, когда ему была передана копия уточненного расчета финансового результата инвестиционного товарищества.\n\nПри этом, если уточненная налоговая декларация (расчет) представляется в налоговый орган в сроки, указанные в абзаце втором настоящего пункта, участник договора инвестиционного товарищества, не являющийся управляющим товарищем, ответственным за ведение налогового учета, освобождается от ответственности.\n\nЕсли участник договора инвестиционного товарищества обжалует акты или решения налогового органа, которыми были изменены финансовые результаты инвестиционного товарищества, он обязан представить уточненную налоговую декларацию (расчет) не позднее пятнадцати дней со дня, когда вышестоящим налоговым органом было принято решение по результатам рассмотрения его жалобы.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 81. Внесение изменений в налоговую декларацию, расчеты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b428fa77b406da5c9f01a34a1059559b7af40d1470f00c1f76dbb45eb0e58796"}]$law7d0063$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
